'use strict';
(()=>{
const V=window.AITUTOR_V9=window.AITUTOR_V9||{},P=V.contentPacks?.authored;if(!P)return;
const M={
E01:{a:'응급의료서비스는 신고·현장대응·이송·의료기관 인계가 끊기지 않는 하나의 체계로 이해한다. 현장 처치만 따로 외우기보다 각 단계의 역할과 정보 전달을 연결해서 본다.',b:'응급구조사의 업무는 법적 범위와 의료지도, 기록 책임을 함께 고려한다. 할 수 있는 처치와 해야 할 보고·기록을 구분하는 문제가 자주 출제된다.',trap:'개인의 임의판단과 체계 안에서 허용된 역할을 혼동하지 않는다.'},
E02:{a:'구급대원의 안전은 환자처치보다 먼저 확인한다. 위험한 현장에 무리하게 진입하면 구조자가 추가 환자가 되어 전체 구조능력이 떨어질 수 있다.',b:'반복되는 중증환자·사망·폭력현장 노출은 정신적 스트레스를 만들 수 있으므로 동료지원, 휴식, 상담 등 회복체계를 활용하는 관점도 함께 본다.',trap:'환자에게 빨리 접근하는 것이 항상 가장 우선이라는 선지를 경계한다.'},
E03:{a:'감염관리는 모든 환자 접촉에서 표준주의를 기본으로 하고, 예상되는 노출경로에 따라 장갑·마스크·보안경 등 개인보호장비를 선택하는 흐름으로 이해한다.',b:'세척·소독·멸균은 목적과 적용대상이 다르다. 위험물 현장에서는 물질 확인, 오염확산 방지, 제염 전후 구역 구분이 환자평가와 동시에 고려된다.',trap:'소독과 멸균을 같은 수준의 처리로 보거나 오염된 장비를 즉시 재사용하는 선택지를 주의한다.'},
E04:{a:'해부생리는 구조의 이름을 외우는 데서 끝나지 않고 각 기관이 기도·호흡·순환·신경기능과 어떻게 연결되는지를 환자평가에 적용해야 한다.',b:'해부학적 위치와 방향용어를 정확히 알아야 통증·상처·변형 위치를 의료진에게 일관되게 전달할 수 있다.',trap:'장기의 위치와 기능, 해부학적 방향을 뒤바꾼 선택지를 먼저 걸러낸다.'},
E05:{a:'현장 의사소통은 짧고 명확하게 환자상태·처치·변화를 전달하는 것이 핵심이다. 무선통신에서는 불필요한 개인정보를 줄이고 필요한 임상정보를 구조화해 전달한다.',b:'기록은 관찰한 사실, 환자 진술, 시행한 처치와 반응, 시간을 구분해서 남겨야 한다. 나중에 다른 의료진이 같은 상황을 재구성할 수 있어야 좋은 기록이다.',trap:'추정이나 평가자의 감정을 객관적 사실처럼 기록하지 않는다.'},
E06:{a:'환자 이동 전에는 이동 필요성, 예상 경로, 필요한 인원과 장비, 환자의 위험요인을 먼저 계획한다. 무리한 들기는 환자와 대원 모두에게 손상을 줄 수 있다.',b:'신체역학은 하중을 몸에 가깝게 두고 안정된 자세로 움직이는 원칙을 중심으로 이해하며, 환자상태에 따라 들것·계단장비·이송장비를 선택한다.',trap:'모든 환자를 같은 자세·같은 장비로 이동시키는 접근을 피한다.'},
E07:{a:'응급장비는 이름 암기보다 목적, 사용 전 점검, 적용 대상, 사용 중 환자 반응 확인 순서로 공부한다. 장비가 있어도 올바른 적응증과 준비가 없으면 효과가 떨어진다.',b:'기도·호흡·순환·외상·이송 장비는 서로 독립된 물품 목록이 아니라 ABC와 환자 이동 흐름에 맞춰 선택하는 도구다.',trap:'장비 사용 자체를 처치 목표로 착각하지 말고 환자의 생리적 문제를 먼저 확인한다.'},
E08:{a:'환자평가는 현장확인 → 1차평가 → 병력·2차평가 → 재평가의 흐름으로 반복된다. 생명을 위협하는 문제를 발견하면 전체 문진이 끝날 때까지 기다리지 않고 우선 처치한다.',b:'비외상과 외상은 평가의 강조점이 다르지만 환자의 전반적 인상, 의식, 기도·호흡·순환, 주요 병력과 변화 추적은 공통 축이다.',trap:'1차평가와 2차평가를 단순한 순서 암기로만 보고 위급상황에서도 다음 단계까지 기다리는 오류를 피한다.'},
E09:{a:'기도유지는 공기가 폐까지 이동할 통로를 확보하는 것이 목표다. 의식수준, 기도폐쇄 징후, 분비물·구토물 여부를 평가한 뒤 자세, 흡인, 보조기구, 환기 방법을 선택한다.',b:'기도보조기구는 환자의 반사와 상태에 맞게 선택해야 하며, 삽입 후에도 흉곽 움직임·호흡상태·산소화 변화를 계속 확인해야 한다.',trap:'기도보조기구를 넣었다는 사실만으로 기도가 안전하게 유지된다고 단정하지 않는다.'},
E10:{a:'호흡곤란에서는 호흡수만 보는 것이 아니라 호흡노력, 흉곽 움직임, 피부상태, 의식변화, 말하기 능력 등 전체적인 호흡상태를 함께 본다.',b:'호흡곤란이 진행해 환기능력이 떨어지는지, 원인이 기도·폐·심장·독성흡입 등 어디에 가까운지를 평가해 산소와 환기보조 필요성을 결정한다.',trap:'빠른 호흡을 모두 효과적인 환기로 판단하지 않는다.'},
E11:{a:'응급 심장질환은 흉통·호흡곤란·실신 등 증상에서 심각한 심혈관 원인을 놓치지 않는 것이 중요하고, 심정지로 진행하면 즉시 고품질 소생술과 제세동 흐름으로 전환한다.',b:'AED는 리듬을 분석해 제세동 필요 여부를 안내하는 장비이며, 분석·충격 시 환자와 접촉하지 않고 충격 전후 가슴압박 중단을 최소화하는 흐름을 이해한다.',trap:'모든 심정지 리듬에 충격을 시행하는 것으로 외우지 않는다.'},
E12:{a:'급성 복통은 통증 위치만으로 원인을 단정하지 않고 OPQRST와 SAMPLE, 활력징후, 복부 소견, 동반증상을 함께 수집한다.',b:'복통은 심혈관·위장관·비뇨기·생식기 등 여러 원인으로 나타날 수 있어 쇼크 징후나 출혈 가능성처럼 생명을 위협하는 단서를 먼저 찾는다.',trap:'통증이 약하다는 이유만으로 중증질환 가능성을 배제하지 않는다.'},
E13:{a:'출혈 평가는 보이는 외부출혈뿐 아니라 내부출혈 가능성과 쇼크 징후를 동시에 본다. 대량 외부출혈은 즉시 지혈하고 이후 기도·호흡·순환 상태를 반복 확인한다.',b:'쇼크는 조직관류가 충분하지 않은 상태라는 관점으로 이해하면 빈맥·피부변화·의식변화 등 여러 징후를 하나의 흐름으로 연결할 수 있다.',trap:'혈압이 유지된다는 이유만으로 초기 쇼크를 배제하지 않는다.'},
E14:{a:'연부조직 손상은 개방성·폐쇄성 손상, 출혈, 오염, 조직손상 정도를 평가하고 지혈과 상처보호를 우선한다.',b:'화상은 원인, 깊이, 범위, 부위, 기도손상 가능성을 함께 평가한다. 화상부위만 보지 말고 연기흡입·동반외상·순환상태를 함께 확인한다.',trap:'화상 면적만으로 중증도를 판단하지 않는다.'},
E15:{a:'근골격계 손상은 통증·부종·변형뿐 아니라 손상 부위 원위부의 감각·운동·순환상태를 확인하는 것이 중요하다.',b:'부목은 추가 손상과 통증을 줄이기 위한 수단이며 적용 전후 신경혈관 상태를 비교하고, 생명을 위협하는 문제가 있으면 부목보다 ABC 처치를 우선한다.',trap:'변형된 사지를 무조건 정상모양으로 맞추는 것으로 이해하지 않는다.'},
E16:{a:'머리·척추 손상은 손상기전, 의식수준, 신경학적 변화, 호흡과 순환을 함께 평가한다. 겉으로 상처가 작아도 중추신경계 손상이 심할 수 있다.',b:'척추 손상이 의심되면 불필요한 움직임을 줄이고 기도를 안전하게 유지해야 하며, 헬멧 제거 같은 조작은 환자 상태와 기도 접근 필요성을 고려해 팀으로 시행한다.',trap:'손상기전만으로 손상 유무를 확정하거나 정상 의식만으로 중증 손상을 배제하지 않는다.'},
E17:{a:'의식장애는 원인이 다양하므로 혈당문제·경련·뇌졸중·저산소·중독·외상 등 가역적이고 시간에 민감한 원인을 빠르게 확인한다.',b:'경련이 끝난 뒤에는 기도와 호흡을 재평가하고 손상을 확인한다. 뇌졸중은 증상 발생 또는 마지막 정상 시각을 확인해 신속한 이송·인계에 반영한다.',trap:'경련 중 입 안에 물건을 강제로 넣거나 환자를 억지로 고정하지 않는다.'},
E18:{a:'중독은 노출경로, 물질, 양, 시각, 증상을 파악하고 구조자 오염을 막는 것이 먼저다. 현장 물질정보와 용기·라벨은 안전하게 확보해 의료진에게 전달한다.',b:'알레르기 반응은 피부증상만 있는지, 기도부종·호흡곤란·순환저하가 동반되는 중증 반응인지 구분해 평가한다.',trap:'원인물질을 확인하려고 구조자가 위험구역에 무보호로 들어가지 않는다.'},
E19:{a:'환경응급은 체온조절 실패와 환경노출을 함께 본다. 한랭·고온 손상 모두 환자를 위험환경에서 분리하고 ABC와 의식, 피부상태를 반복 평가한다.',b:'익수환자는 호흡저하와 저산소 문제가 우선이며, 물림·쏘임에서는 국소손상뿐 아니라 전신 알레르기 반응과 독성 증상을 함께 확인한다.',trap:'체온 수치 하나만 보고 환자의 전신상태를 놓치지 않는다.'},
E20:{a:'산과환자는 임신주수, 진통 간격, 파수, 출혈, 태동, 분만력 등을 확인해 즉시 분만 가능성과 산모·태아 위험을 함께 평가한다.',b:'정상 분만에서는 산모와 신생아의 안전·보온·기도와 호흡을 연속적으로 확인하고, 비정상 태위·과다출혈·경련 등 합병증 징후가 있으면 신속한 지원과 이송을 준비한다.',trap:'분만 과정만 보느라 산모의 출혈·쇼크나 신생아의 호흡상태를 놓치지 않는다.'},
E21:{a:'소아는 연령에 따라 기도 크기, 호흡양상, 활력징후와 의사소통 방식이 달라 성인 기준을 그대로 적용하지 않는다.',b:'평가에서는 외관·호흡노력·순환상태를 빠르게 보고 보호자에게 평소상태와 증상 변화를 확인한다. 학대·방임이 의심되면 객관적인 관찰과 기록을 남긴다.',trap:'울고 움직이는 소아라는 이유만으로 호흡·순환 악화를 배제하지 않는다.'},
E22:{a:'노인환자는 만성질환, 여러 약물, 감각·인지 변화로 전형적인 증상이 약하게 나타날 수 있어 평소 기능상태와 현재 변화의 차이를 확인하는 것이 중요하다.',b:'낙상·탈수·감염·약물관련 문제 등 여러 원인이 함께 있을 수 있으므로 한 가지 진단명에 너무 빨리 고정하지 않고 전체 평가를 반복한다.',trap:'나이 탓으로 증상을 정상 노화라고 단정하지 않는다.'},
E23:{a:'행동응급에서는 현장 안전과 환자·대원·주변인의 위험을 먼저 평가하고, 자극을 줄인 환경에서 차분하고 단순한 의사소통을 사용한다.',b:'행동 변화가 정신과적 원인만이 아니라 저산소·저혈당·중독·외상 등 의학적 원인에서도 생길 수 있어 기본 신체평가를 생략하지 않는다.',trap:'환자의 행동을 평가자의 주관적 표현으로 기록하지 않고 관찰 가능한 행동과 발언을 객관적으로 남긴다.'},
E24:{a:'기본소생술은 반응과 호흡을 빠르게 확인하고 도움 요청·AED 확보·고품질 가슴압박·적절한 환기·제세동을 중단 없이 연결하는 체계로 이해한다.',b:'성인 가슴압박은 교재의 속도·깊이·완전한 이완·중단 최소화 기준을 함께 지키며, 이물질 기도폐쇄는 환자의 의식과 기침 가능 여부에 따라 대응을 달리한다.',trap:'맥박·호흡 확인이나 제세동 때문에 가슴압박 중단이 길어지지 않게 한다.'}
};
for(const c of V.curriculum.ems.flatMap(sc=>sc.concepts.map((title,i)=>({scope:sc,id:`${sc.id}-C${String(i+1).padStart(2,'0')}`,title})))){
  const p=P[c.id],m=M[c.scope.id];if(!p||!m)continue;
  const source=V.sourceLabel(c.id);
  p.detail=[...(p.detail||[]),`${c.title} 학습에서는 개념 정의만 외우지 말고 환자에서 무엇을 먼저 확인하고 다음 단계로 어떻게 연결하는지 순서로 정리한다.`];
  p.deepSections=[...(p.deepSections||[]),
    {title:`${c.scope.title} · 평가 흐름`,body:m.a,bullets:[`현재 세부개념: ${c.title}`,source]},
    {title:'처치·판단 연결',body:m.b,bullets:['생명을 위협하는 문제를 먼저 처리하고 처치 후 반응을 재평가한다.']},
    {title:'시험에서 틀리기 쉬운 지점',body:m.trap,bullets:['단일 징후 하나만으로 결론 내리지 않고 전체 환자상태와 흐름을 본다.']}
  ];
  p.emsDepth2026=true;
}
V.emsRich2026={scopes:Object.keys(M).length,concepts:V.curriculum.concepts.filter(c=>c.subject==='ems'&&P[c.id]?.emsDepth2026).length,source:'2026 소방전술3(구급) page-ranged concepts'};
})();
;

