rename('E01-C03','응급구조사 법적책임·119구급대 법령');
add('E01-C03',{
  source:'119구조ㆍ구급에 관한 법률 · 119법 시행령 · 국가법령정보센터',
  detail:[
    '119법 시행령은 119구급대를 일반구급대와 고속국도구급대로 구분해 편성·운영하도록 규정한다. 일반구급대는 원칙적으로 소방서마다 1개 대 이상 설치하며, 소방서가 없는 시·군·구는 중심지의 119안전센터에 설치할 수 있다.',
    '구급대원 자격은 소방공무원 중 의료인, 1급 응급구조사, 2급 응급구조사 또는 소방청장이 실시하는 구급업무 교육을 받은 사람으로 규정된다. 다만 교육만 받은 사람은 구급차 운전과 구급 보조업무만 할 수 있다.',
    '119법은 위급상황에서 구조·구급대를 신속히 출동시켜 인명구조, 응급처치와 이송 등 필요한 활동을 하도록 하고, 시행령은 비응급환자의 경우 병력·증상·주변상황을 종합해 응급 여부를 판단한 뒤 일정 요건에서 출동 요청을 거절할 수 있도록 규정한다.',
    '119구급상황관리센터는 의료인 또는 1·2급 응급구조사 자격을 가진 사람을 배치해 24시간 근무체제를 유지한다.',
    '항공구조구급대는 초고층 건축물 등의 인명구조나 도서·벽지 응급환자의 긴급 이송을 위해 편성·운영한다. 시행령은 국제구조·국제구급대원의 파견 전 감염병 대비 조치와 철수 후 부상·감염병·외상 후 스트레스 장애 등에 대한 검진도 규정한다.'
  ],
  must:[
    '구급대원 자격 → 의료인 · 1급 응급구조사 · 2급 응급구조사 · 소방청 구급교육 이수자',
    '구급교육 이수자만 해당 → 구급차 운전 + 구급 보조업무',
    '일반구급대 → 원칙적으로 소방서마다 1개 대 이상',
    '119구급상황관리센터 → 의료인/1·2급 응급구조사 배치 · 24시간 근무',
    '항공구조구급대 → 초고층 인명구조 · 도서/벽지 응급환자 긴급 이송'
  ],
  traps:[
    '소방청 구급교육만 받은 대원이 의료인·응급구조사와 동일한 범위의 응급처치를 한다고 보지 않는다.',
    '비응급이라는 이유만으로 자동 거절하는 것이 아니다. 시행령은 병력·증상·주변상황을 종합해 응급 여부를 판단하도록 한다.',
    '119구급상황관리센터의 자격 인력을 주간에만 배치한다고 보지 않는다. 시행령은 24시간 근무체제를 규정한다.'
  ],
  compare:[
    ['일반구급대','원칙적으로 소방서마다 1개 대 이상'],
    ['고속국도구급대','교통사고 발생빈도 등을 고려해 소방청·시도본부·관할 소방서에 설치 가능'],
    ['항공구조구급대','초고층 등 인명구조 · 도서/벽지 응급환자 긴급이송'],
    ['119구급상황관리센터','의료인·1급·2급 응급구조사 자격 인력 · 24시간']
  ],
  deepSections:[
    sec('구급대원 자격과 업무범위','시험에서는 “누가 구급대원이 될 수 있는가”와 “교육 이수자에게 허용되는 업무가 무엇인가”를 분리해 읽는다. 의료인·1급·2급 응급구조사와 달리 소방청 구급교육 이수자는 구급차 운전과 구급 보조업무만 할 수 있다.'),
    sec('출동과 비응급 거절','119법은 위급상황 출동을 원칙으로 두고, 시행령은 비응급환자 거절 가능 사유를 별도로 둔다. 비응급 여부는 병력·증상·주변상황을 종합해 판단한다.'),
    sec('항공·국제구급','항공구조구급대는 초고층·도서·벽지 등 지상대 접근이 어렵거나 긴급 이송이 필요한 상황과 연결된다. 국제구급대원은 파견 전 감염병 대비와 철수 후 건강검진 규정도 함께 본다.')
  ],
  officialLinks:[
    {label:'119법 · 구조·구급활동(제13조)',url:'https://law.go.kr/LSW/lsLinkCommonInfo.do?lsJoLnkSeq=1032838931'},
    {label:'119법 시행령 · 구급대 편성·자격·이송(제10~12조)',url:'https://law.go.kr/lsLinkCommonInfo.do?lspttninfSeq=104191'},
    {label:'119법 시행령 · 구급상황관리센터·재외국민 서비스',url:'https://law.go.kr/lsLinkCommonInfo.do?lspttninfSeq=104193'},
    {label:'119법 시행령 · 비응급 구조·구급 요청 거절',url:'https://law.go.kr/lsLinkCommonInfo.do?lspttninfSeq=104196'}
  ]
});

rename('E05-C04','기록지·중증도 분류');

add('E05-C04',{
  detail:[
    '대량환자 발생 시 중증도 분류는 제한된 인력과 자원을 가장 위급한 환자에게 우선 배분하기 위한 과정이다. 교재는 현장에서 긴급·응급·비응급·지연으로 신속히 분류하고 우선순위에 따라 처치와 분산 이송을 결정하도록 설명한다.',
    'START 분류는 먼저 걸을 수 있는 환자를 분리한 뒤 남아 있는 환자의 호흡·맥박·의식을 빠르게 확인해 분류하고, 지정 장소로 이동한 환자도 다시 평가하는 흐름으로 제시된다.'
  ],
  must:[
    'START 첫 단계 → 걸을 수 있는 환자부터 지정 장소로 이동',
    '남은 환자 → 호흡 · 맥박 · 의식 순으로 빠르게 확인',
    '분류 후 끝이 아니라 재평가를 반복'
  ],
  traps:[
    'START를 병원 도착 후 시행하는 분류로만 설명하지 않는다.',
    '한 번 분류한 색상은 절대 바뀌지 않는다고 보지 않는다. 상태 변화에 따라 재평가한다.'
  ],
  compare:[
    ['긴급','즉시 처치·이송 우선순위가 높은 환자'],
    ['응급','중대한 손상이 있으나 긴급군 다음 우선순위'],
    ['비응급','손상이 국한되고 일정 시간 지연을 견딜 수 있는 환자'],
    ['지연','교재상 사망 또는 생존 가능성이 매우 낮은 상태를 포함']
  ],
  deepSections:[
    sec('START 순서','걷기 가능 여부로 1차 분리한 뒤 호흡·맥박·의식을 빠르게 확인하고 분류한다. 분류표시는 처치 종료가 아니라 다음 처치·이송 우선순위를 정하기 위한 표지다.'),
    sec('시험에서 자주 섞는 포인트','중증도 분류의 목적, 색상 의미, START 확인 순서, 재평가 필요성을 서로 바꿔 놓은 선지를 구분한다.')
  ]
});

rename('E03-C05','위험물·CBRN 현장 구급·제독');
add('E03-C05',{
  source:'2026 소방전술3(구급) 44~50쪽',
  detail:[
    '위험물사고 현장은 위험물 종류를 모른 채 성급히 진입하는 것이 초기 대응팀 부상의 주요 원인이 될 수 있다. 교재는 사고구역의 용도, 용기 모양, 표시·색깔, 플래카드/라벨, 환자들의 공통 증상과 징후 등을 이용해 위험물질을 먼저 평가하도록 설명한다.',
    '보호복이 없거나 위험물 대응교육·훈련을 받지 않은 구급대원은 안전구역에서 대기한다. 현장진입 시에는 가스·증기·액체의 체류 가능성을 고려해 고지대에서 바람을 등지고 접근하고, 건물 내부라면 환기구 주변 대기를 피하도록 제시한다.',
    '사고 안전계획에는 물리·화학적 위험물질, 기상, 사고관리체계, 현장 통제범위, 개인보호장비 등급, 환자·장비 제독물품, 각 팀 역할, 공기오염 측정, 대피절차와 경로가 포함된다. 진입 전 안전브리핑에서는 작업계획과 커뮤니케이션 시스템, 비상징후·대피로, 제독계획을 공유한다.',
    '현장은 오염구역, 오염통제구역, 안전구역의 세 구역으로 나눈다. 오염구역에서는 환자를 빠르게 이동시키고 오염된 의복·악세사리와 사용 장비를 현장에 남겨 오염 확산을 줄인다.',
    '오염통제구역은 제독 텐트 등이 위치하는 완충구역이다. 오염 의복은 벗겨 밀봉하고 제독을 시행한다. 이 구역에서의 구급처치는 기도·호흡·순환, 지혈, 경추고정, CPR, 전신중독 평가 등 기본 처치를 중심으로 하고 정맥로 같은 침습적 술기는 가급적 제독 후 안전구역에서 시행한다.',
    '안전구역에서는 현장지휘·자원대기와 함께 구급대원이 활동하고, 대량환자 발생 시 중증도분류 후 우선순위에 따라 이송한다. 귀소 후에는 차량·장비·대원에 대한 2차오염 방지와 제독 확인, 위험물질 접촉보고까지 이어진다.'
  ],
  must:[
    '무보호·미훈련 구급대원 → 안전구역 대기',
    '현장 3구역 → 오염구역 · 오염통제구역 · 안전구역',
    '진입 전 안전브리핑 → 작업계획 · 통신 · 대피로 · 제독계획',
    '오염통제구역 → 제독 + 기본 인명소생 중심',
    '침습적 술기 → 가급적 제독 후 안전구역에서',
    '안전구역 → 중증도분류 후 우선순위 이송'
  ],
  traps:[
    '냄새가 없고 눈에 보이지 않는다는 이유로 위험물질이 없다고 판단하지 않는다.',
    '오염구역의 환자에게 사용한 장비를 제독 없이 안전구역에서 재사용하지 않는다.',
    '보호장비·훈련이 없는 구급대원이 환자를 빨리 처치하려고 오염구역에 진입하는 선지를 주의한다.',
    '정맥로 확보 같은 침습적 술기를 제독보다 무조건 먼저 시행한다고 보지 않는다.'
  ],
  compare:[
    ['오염구역','위험물질 존재 · 빠른 환자이동 · 오염확산 최소화'],
    ['오염통제구역','오염구역과 안전구역 사이 · 제독텐트 · 기본구급'],
    ['안전구역','현장지휘·자원대기 · 구급활동 · 중증도분류·이송']
  ],
  flow:['현장평가·위험물 식별','통제구역·PPE 설정','오염구역 구조','오염통제구역 제독','안전구역 처치·분류·이송','귀소 후 2차오염 방지'],
  visuals:['ems-hazmat-zones'],
  deepSections:[
    sec('현장 안전계획','위험물 종류만 확인하는 것이 아니라 기상·지형·오염범위·사고관리체계·팀 역할·공기측정·대피경로·제독물품을 한 세트로 준비한다.'),
    sec('3구역 동선','환자와 대원은 오염구역 → 오염통제구역(제독) → 안전구역 순으로 오염을 끊어가며 이동한다. 안전구역을 오염 장비가 다시 오염시키지 않도록 한다.'),
    sec('처치 우선순위','오염통제구역에서는 생명을 위협하는 기본 처치에 집중하고, 정맥로 같은 침습적 처치는 가급적 제독 후 안전구역에서 시행해 2차오염과 대원 노출을 줄인다.')
  ]
});

rename('E21-C04','기도·호흡·소아소생 기초');
add('E21-C04',{
  source:'2026 소방전술3(구급) 368~372쪽 · 응급 심장질환 212쪽',
  detail:[
    '소아는 호흡기계 문제가 빠르게 악화되어 심정지로 이어질 수 있다. 교재는 저산소증이 느린맥을 초래할 수 있고, 느린맥이 나타나면 저산소증을 가정해 즉시 고농도 산소를 제공하며 필요하면 BVM 또는 포켓마스크로 인공호흡하도록 설명한다.',
    '소아 기도는 짧고 좁으며 유연하고 혀가 상대적으로 커서 과신전이나 분비물만으로도 폐쇄되기 쉽다. 기도개방은 목을 과도하게 젖히지 않고 시행하며 호흡곤란에서 비익확장·호흡보조근 사용·비정상 호흡음을 반복 평가한다.',
    '교재의 심장충격기 부분은 1세 미만 영아에서 소아용 패드나 에너지 조절장치가 없을 경우에도 성인용 심장충격기를 사용할 수 있으며 2~4J/kg으로 제세동하도록 제시한다. 심실세동과 무맥성 심실빈맥은 대표적인 제세동 적응 리듬으로 연결된다.',
    '소아 쇼크는 빠른호흡, 차갑고 창백·축축한 피부, 약하거나 촉지되지 않는 말초맥박, 모세혈관 재충혈 지연, 의식변화, 소변량 감소 등을 함께 본다. 교재의 저혈량쇼크 표는 중증도가 커질수록 말초관류와 의식, 소변량이 악화되는 흐름을 제시한다.',
    '이 학습팩은 2026 중앙소방학교 교재에 직접 확인되는 병원 전 소아 기도·호흡·쇼크·제세동 기초만 다룬다. 약물용량을 포함한 전문소아소생술 전체 서맥·빈맥 알고리즘은 별도 공식근거가 확보될 때까지 확정 범위로 표시하지 않는다.'
  ],
  must:[
    '소아 호흡문제 → 빠른 저산소증·느린맥·심정지 위험',
    '느린맥 + 저산소 의심 → 고농도 산소 · 필요 시 BVM/포켓마스크 환기',
    '1세 미만 영아 제세동(교재 조건) → 2~4 J/kg',
    '소아 VF·무맥성 VT → 제세동 적응 리듬',
    '소아 쇼크 → 호흡·피부·말초맥박·모세혈관재충혈·의식·소변량을 함께 평가'
  ],
  traps:[
    '소아를 단순한 성인 축소판으로 보고 기도 크기·머리 위치·호흡보상 차이를 무시하지 않는다.',
    '느린맥을 심장 문제 하나로만 보고 저산소증 교정을 늦추지 않는다.',
    '맥박과 호흡이 있는 모든 빈맥을 제세동 대상으로 보지 않는다.',
    '현재 교재 근거 밖의 전문소아 약물·빈맥 알고리즘을 이 학습팩의 확정 내용으로 확대하지 않는다.'
  ],
  compare:[
    ['호흡곤란 초기','빠른호흡 · 비익확장 · 호흡보조근 · 고농도산소·재평가'],
    ['저산소 악화','느린맥 가능 · 즉시 산소 · 필요 시 BVM/포켓마스크'],
    ['VF·무맥성 VT','제세동 적응 리듬'],
    ['쇼크 진행','말초관류·의식·소변량 악화 · 신속 이송']
  ],
  flow:['소아 일반적 인상','기도·호흡 평가','산소화·환기 보조','순환·쇼크 평가','심정지 시 CPR·제세동 체계'],
  visuals:['ems-pediatric-resuscitation'],
  deepSections:[
    sec('왜 소아는 호흡이 먼저인가','교재는 소아에서 호흡기계 문제가 흔히 심장마비로 이어진다고 설명한다. 따라서 느린맥이 보이면 맥박 숫자만 보지 말고 저산소와 환기 문제를 우선 연결한다.'),
    sec('제세동 기초','영아에서는 소아용 감쇠 장치가 우선이지만 교재 조건에서 장치가 없을 때 성인용 심장충격기를 2~4J/kg으로 사용할 수 있다. VF·무맥성 VT처럼 맥박이 없는 충격가능 리듬과 연결한다.'),
    sec('소아 쇼크 읽기','초기에는 빠른 맥박과 말초관류 저하가 나타날 수 있고 악화할수록 맥박촉지·혈압·의식·소변량이 나빠진다. 단일 숫자보다 전체 관류상태와 추세를 본다.')
  ]
});

rename('E07-C03','순환유지 장비·수액 주입 계산');
add('E07-C03',{
  source:'2026 소방전술3(구급) 순환유지 장비 · 표준 수액 점적 계산(교육 보강)',
  detail:[
    '수액 주입속도 계산은 총 주입량, 총 주입시간, 사용하는 수액세트의 점적계수(drop factor)를 서로 연결하는 단위계산이다.',
    '분당 방울 수(gtt/min)는 총 주입량(mL) × 점적계수(gtt/mL)를 총 주입시간(분)으로 나누어 계산한다. 시간당 주입량(mL/hr)은 총 주입량(mL)을 총 시간(hr)으로 나눈다.',
    '현재 2026 중앙소방학교 공개 구급교재에서 이 점적 계산식을 직접 확인하지 못했으므로, 시험범위 Coverage에서는 “부분”으로 유지하고 연습문제만 제공한다. 계산식 자체는 보건의료 교육에서 사용하는 표준 단위계산이다.'
  ],
  must:[
    'gtt/min = 총 주입량(mL) × 점적계수(gtt/mL) ÷ 총 주입시간(min)',
    'mL/hr = 총 주입량(mL) ÷ 총 주입시간(hr)',
    '시간(hr)을 분(min)으로 바꾸는 단계에서 ×60을 빠뜨리지 않기'
  ],
  traps:[
    'gtt/min 계산에서 시간을 시간 단위로 그대로 넣지 않는다.',
    '점적계수(gtt/mL)를 시간당 주입량(mL/hr)과 같은 단위로 보지 않는다.',
    '현재 공개 소방교재에서 계산식 자체가 확인됐다고 과장하지 않는다.'
  ],
  compare:[
    ['mL/hr','주입펌프 등에서 쓰는 시간당 용량'],
    ['gtt/min','중력식 수액세트에서 분당 방울 수'],
    ['점적계수','수액세트가 1mL당 만드는 방울 수(gtt/mL)']
  ],
  calculations:[
    {title:'분당 점적수',formula:'gtt/min = 총량(mL) × 점적계수(gtt/mL) ÷ 시간(min)',note:'표준 단위계산 연습. 현재 2026 공개 소방교재의 수식 직접근거는 미확인.',example:'1000mL, 8시간, 20gtt/mL → 1000×20÷480 ≈ 41.7 → 약 42gtt/min',evidenceTier:'standard-education-practice'},
    {title:'시간당 주입량',formula:'mL/hr = 총량(mL) ÷ 시간(hr)',note:'주입펌프 속도 환산의 기본식.',example:'1000mL를 8시간 → 125mL/hr',evidenceTier:'standard-education-practice'}
  ],
  deepSections:[
    sec('단위부터 맞추기','분당 방울 수는 분(min)을 사용한다. 문제에 시간이 hr로 주어지면 먼저 ×60으로 분으로 바꾼 뒤 계산한다.'),
    sec('실전 함정','총량·시간·점적계수 중 하나를 누락하거나 60을 곱해야 할 자리에 나누는 오류가 가장 흔하다. 계산 전 단위를 식 옆에 직접 적는 습관을 만든다.'),
    sec('근거 수준','점적 계산은 표준 보건의료 교육 내용으로 연습 가치가 있지만, 현재 2026 공개 소방교재에서 해당 수식을 직접 확인하지 못했으므로 공식교재 Verified로 승격하지 않는다.')
  ]
});

add('E21-C04',{
  source:'2026 소방전술3(구급) · 2020년 한국심폐소생술 가이드라인(질병관리청·대한심폐소생협회)',
  detail:[
    '2020 한국심폐소생술 가이드라인의 소아 전문소생술은 심장정지에서 고품질 CPR과 리듬에 따른 제세동 여부, 혈관로/골내로, 약물, 가역적 원인 교정을 함께 진행한다.',
    '소아 심장정지에서 에피네프린은 0.01mg/kg IV/IO를 3~5분마다 반복하고, 제세동 후에도 지속되는 심실세동/무맥성 심실빈맥에서는 아미오다론 5mg/kg 또는 리도카인을 고려한다.',
    '소아 서맥은 산소화·환기를 먼저 교정하고 심박수와 관류상태를 함께 본다. 산소와 환기에도 의식저하·저혈압·쇼크와 함께 분당 60회 미만 서맥이 지속되면 전문치료를 진행하며, 미주신경 긴장 또는 특정 전도장애 상황에서는 아트로핀 0.02mg/kg IV/IO를 고려한다.',
    '소아 빈맥은 12유도 심전도로 QRS 간격을 확인해 좁은 QRS(≤0.09초)와 넓은 QRS(>0.09초)를 구분한다. 규칙적인 심실상빈맥에서 아데노신 0.1mg/kg(최대 6mg), 필요 시 0.2mg/kg(최대 12mg)을 고려한다.',
    '혈역학적으로 불안정한 소아 빈맥은 동기화 심장율동전환을 0.5~1J/kg으로 시작하고 실패하면 2J/kg으로 증량한다.'
  ],
  must:[
    '소아 심정지 에피네프린 → 0.01mg/kg IV/IO · 3~5분마다',
    '불응성 VF/pVT → 아미오다론 5mg/kg 또는 리도카인 고려',
    '소아 서맥 → 먼저 산소화·환기 + 관류상태 평가',
    '소아 SVT 아데노신 → 0.1mg/kg(최대 6mg) → 0.2mg/kg(최대 12mg)',
    '불안정 빈맥 동기화 심율동전환 → 0.5~1J/kg → 2J/kg'
  ],
  traps:[
    '소아 서맥에서 약물보다 산소화·환기 교정을 늦추지 않는다.',
    '아데노신을 불규칙한 넓은 QRS 빈맥에 무조건 투여한다고 외우지 않는다.',
    '소아 심정지 에피네프린 0.01mg/kg과 성인 심정지 1mg 용량을 섞지 않는다.',
    '동기화 심율동전환과 제세동의 적응 리듬·에너지를 같은 것으로 보지 않는다.'
  ],
  compare:[
    ['심장정지','고품질 CPR · 리듬평가 · 필요 시 제세동 · 에피네프린 · 가역원인'],
    ['증상성 서맥','산소화/환기 우선 · 관류상태 · 에피네프린/상황별 아트로핀 · 필요 시 조율'],
    ['안정된 SVT','좁고 규칙적 QRS 확인 · 미주신경수기/아데노신 고려'],
    ['불안정 빈맥','동기화 심율동전환 0.5~1J/kg → 필요 시 2J/kg']
  ],
  deepSections:[
    sec('소아 심정지 흐름','CPR을 시작하고 리듬을 평가한다. 충격가능리듬이면 제세동과 CPR을 반복하며, 혈관로를 확보해 에피네프린과 불응성 리듬의 항부정맥제를 고려하고 Hs & Ts 같은 가역원인을 교정한다.'),
    sec('서맥 흐름','기도·호흡·산소화가 원인인 경우가 많으므로 먼저 환기와 산소공급을 최적화한다. 관류가 나쁘고 서맥이 지속되면 약물과 필요 시 조율을 연결한다.'),
    sec('빈맥 흐름','QRS 폭과 규칙성, 혈역학적 안정성을 먼저 구분한다. 안정된 규칙적 SVT는 아데노신을 고려하고, 불안정 빈맥은 동기화 심율동전환을 지연하지 않는다.')
  ],
  officialLinks:[
    {label:'2020년 한국심폐소생술 가이드라인',url:'https://www.kacpr.org/download/2020%EB%85%84%20%ED%95%9C%EA%B5%AD%EC%8B%AC%ED%8F%90%EC%86%8C%EC%83%9D%EC%88%A0%20%EA%B0%80%EC%9D%B4%EB%93%9C%EB%9D%BC%EC%9D%B8.pdf'}
  ]
});

rename('E20-C03','정상분만·신생아 초기처치');
add('E20-C03',{
  detail:[
    '2026 소방전술3(구급) 교재는 신생아 상태를 아프가(Apgar) 점수로 평가하며 출생 1분과 5분에 각각 확인하도록 제시한다. 평가 항목은 피부색, 맥박, 반사흥분도, 근육의 강도, 호흡이다.',
    '교재 기준 아프가 8~10점은 기본적인 신생아 관리, 3~7점은 호흡보조·부드러운 자극·입-코 흡인, 0~2점은 심한 질식 상태로 기관내삽관·산소공급·CPR이 필요한 단계로 정리된다.',
    '신생아 초기처치는 보온 유지와 기도 내 이물질 제거가 먼저이며, 교재는 구형흡입기로 입을 먼저 흡인하고 다음에 코를 흡인하도록 설명한다. 코를 먼저 자극하면 헐떡이거나 호흡을 시작하며 입 안의 물질을 흡인할 위험이 있다는 이유를 함께 제시한다.',
    '기도를 정리한 뒤 호흡을 평가하고 30초 안에 자발호흡을 시작하지 않으면 등을 부드럽고 활발하게 문지르거나 발바닥을 손가락으로 자극해 호흡을 격려한다. 발바닥을 들어 손바닥으로 때리는 자극은 하지 않도록 설명한다.'
  ],
  must:[
    'Apgar 평가 시점 → 출생 1분 · 5분',
    'Apgar 5항목 → 피부색 · 맥박 · 반사흥분도 · 근육긴장/활동 · 호흡',
    '교재 초기처치 → 보온 · 기도정리 · 입 먼저, 코 다음 흡인 · 호흡평가'
  ],
  traps:[
    '교재 기준 흡인 순서를 코 → 입으로 바꾸지 않는다.',
    '호흡이 있는데 팔다리에 약간의 청색증만 보인다는 이유로 등을 문지르거나 발바닥을 자극한다고 보지 않는다.',
    'Apgar 1회 점수만 확인하고 5분 재평가를 생략하는 선지를 주의한다.'
  ],
  compare:[
    ['Apgar 8~10점','교재 기준 정상출산 · 기본적인 신생아 관리'],
    ['Apgar 3~7점','교재 기준 호흡보조 · 부드러운 자극 · 입-코 흡인'],
    ['Apgar 0~2점','교재 기준 심한 질식 상태 · 기관내삽관 · 산소공급 · CPR']
  ],
  flow:['보온','입→코 기도정리','호흡평가','필요 시 부드러운 자극','Apgar 재평가·이송'],
  visuals:['ems-newborn-initial'],
  deepSections:[
    sec('Apgar를 한눈에 보기','Apgar는 Appearance, Pulse, Grimace, Activity, Respiration의 다섯 항목을 각각 0~2점으로 보고 출생 1분과 5분에 반복 평가한다. 점수 자체보다 저점수에서 어떤 호흡·소생 보조가 필요한지를 연결해 읽는다.'),
    sec('신생아 초기처치 순서','교재 흐름은 보온 유지와 기도 정리 → 입을 먼저 흡인하고 다음에 코를 흡인 → 호흡 평가 → 필요 시 부드러운 자극으로 이어진다. 정상적으로는 기도 정리 후 30초 안에 자발호흡을 시작하는지를 본다.'),
    sec('시험 함정','입/코 흡인 순서, Apgar 평가 시점, 3개 점수군의 처치를 서로 바꿔 놓은 선택지를 구분한다.')
  ]
});

