    {title:'병원 전 초기 수액량',formula:'0.25 mL × 체중(kg) × 화상면적(%)',note:'교재가 병원 전 초기 주입량의 실용적 기준으로 제시하는 식이다.',example:'60kg × 30% → 0.25×60×30 = 450mL'}
