add('E11-C03',{
  source:'2026 소방전술3(구급) · 2020년 한국심폐소생술 가이드라인 140~145쪽',
  detail:[
    '2020년 한국심폐소생술 가이드라인은 성인 심장정지에서 에피네프린 1mg을 3~5분 간격으로 투여하도록 권고한다. 비제세동 리듬에서는 가능한 빨리 투여하고, 제세동 가능 리듬에서는 신속한 제세동을 우선한 뒤 에피네프린을 투여한다.',
    '불응성 심실세동/무맥성 심실빈맥에서는 아미오다론 또는 리도카인을 고려한다. 아미오다론은 첫 300mg 정맥/골내 투여 후 불응성이면 150mg을 1회 추가할 수 있다.',
    '2026 구급 교재의 심정지 세부상황표도 심정지 환자 약물 기록 항목에 에피네프린과 아미오다론의 최초 투여 시각과 투여횟수를 기록하도록 구성되어 있다.'
  ],
  must:[
    '성인 심정지 에피네프린(2020 KACPR) → 1mg · 3~5분 간격',
    '불응성 VF/pVT → 아미오다론 또는 리도카인 고려',
    '성인 아미오다론(2020 KACPR) → 300mg → 불응 시 150mg 1회 추가'
  ],
  traps:[
    '충격필요리듬에서 약물 때문에 첫 제세동을 지연시키지 않는다.',
    '아미오다론의 성인 심정지 용량과 소아 체중기반 용량을 섞지 않는다.'
  ],
  officialLinks:[
    {label:'2020년 한국심폐소생술 가이드라인',url:'https://www.kacpr.org/download/2020%EB%85%84%20%ED%95%9C%EA%B5%AD%EC%8B%AC%ED%8F%90%EC%86%8C%EC%83%9D%EC%88%A0%20%EA%B0%80%EC%9D%B4%EB%93%9C%EB%9D%BC%EC%9D%B8.pdf'},
  ]
});

add('E11-C05',{
  source:'2020년 한국심폐소생술 가이드라인',
  detail:[
    '2020 가이드라인의 소아 서맥 치료는 미주신경 긴장 또는 항콜린성 약물 독성이 원인인 경우 아트로핀 0.02mg/kg 정맥/골내 투여를 제시한다. 완전 방실차단 또는 동기능부전이 다른 처치에 반응하지 않을 때 경피 심장박동조율을 고려할 수 있다.',
    '소아 심실상빈맥에서는 아데노신을 0.1mg/kg(최대 6mg) 빠르게 투여하고 반응이 없으면 두 번째 0.2mg/kg(최대 12mg)을 고려한다. 안정된 규칙적 넓은 QRS 빈맥에서도 조건에 따라 아데노신을 고려할 수 있다.',
    '소아 빈맥에서 혈역학적으로 불안정하면 동기화 심장율동전환을 고려하며, 가이드라인은 초기 0.5~1J/kg에서 시작하고 실패 시 2J/kg까지 증량하는 흐름을 제시한다.'
  ],
  must:[
    '소아 SVT → 아데노신 0.1mg/kg(최대 6mg) → 필요 시 0.2mg/kg(최대 12mg)',
    '소아 미주신경/항콜린성 관련 서맥 → 아트로핀 0.02mg/kg IV/IO',
    '소아 불안정 빈맥 → 동기화 심장율동전환 0.5~1J/kg → 필요 시 2J/kg'
  ],
  traps:[
    '아데노신을 모든 불규칙 넓은 QRS 빈맥에 일괄 투여한다고 외우지 않는다.',
    '소아 아트로핀·아데노신 용량을 성인 심정지 에피네프린/아미오다론 용량과 섞지 않는다.'
  ],
  officialLinks:[
    {label:'2020년 한국심폐소생술 가이드라인',url:'https://www.kacpr.org/download/2020%EB%85%84%20%ED%95%9C%EA%B5%AD%EC%8B%AC%ED%8F%90%EC%86%8C%EC%83%9D%EC%88%A0%20%EA%B0%80%EC%9D%B4%EB%93%9C%EB%9D%BC%EC%9D%B8.pdf'}
  ]
});

rename('E03-C04','감염 관리·패혈증 주의');
add('E03-C04',{
  source:'2026 소방전술3(구급) 38·43·324쪽',
  detail:[
    '구급대원은 감염성 질환 노출 가능성이 높으므로 정기 건강검진, 예방접종, 감염질환 발생 시 근무제한, 노출 후 적절한 조치 등 감염관리 체계를 유지해야 한다.',
    '교재의 비말전파 관련 예시에는 뇌수막염·폐렴·인플루엔자 등과 함께 패혈증이 제시되지만, 패혈증 자체를 하나의 전파방식으로 정의하는 것은 아니다. 감염원과 전파경로에 맞는 PPE·손위생을 적용하는 것이 핵심이다.',
    '환경응급 장에서는 패혈증 환자가 초기에 열이 오르다가 심한 열 손실을 보일 수 있음을 저체온 위험요인으로 제시한다. 감염 환자의 체온 변화는 단순 발열 여부만으로 중증도를 판단하지 않고 전신상태와 함께 평가한다.',
    '현재 2026 중앙소방학교 교재에서 패혈증의 전체 진단·약물치료 알고리즘까지 상세히 제시하지는 않으므로, 이 학습내용은 감염관리·노출예방·패혈증 경고징후의 연결에 한정한다.'
  ],
  must:[
    '감염관리 → 손위생 · PPE · 예방접종 · 노출 후 조치',
    '감염 전파경로에 맞는 보호조치 적용',
    '패혈증 → 체온 이상이 가능하며 전신상태를 함께 평가'
  ],
  traps:[
    '패혈증이라는 진단명 자체를 “비말로 전파되는 질환”이라고 단순 암기하지 않는다.',
    '예방접종 후 항체가 있다는 이유로 PPE와 손위생을 생략하지 않는다.',
    '발열이 없다는 이유만으로 중증 감염 가능성을 자동 배제하지 않는다.'
  ],
  compare:[
    ['비말주의','큰 호흡기 비말 · 근거리 노출에 마스크 등 보호'],
    ['접촉주의','직접/간접 접촉 · 장갑·손위생·환경오염 관리'],
    ['패혈증 주의','감염에 대한 전신 반응 가능성 · 체온·순환·의식 등 전신상태 함께 평가']
  ]
});

add('F03-C02',{
  source:'2026 소방전술1(화재1) 9쪽 · 2026 소방전술1(화재2) 190·309·345쪽',
  detail:[
    '물질은 고체·액체·기체 상태로 존재할 수 있다. 교재의 물 예시에서는 압력이 일정할 때 온도에 따라 얼음·액체 물·수증기로 상태가 바뀌며, 압력이 달라지면 끓는점도 달라진다고 설명한다.',
    '교재는 0℃의 얼음 1g이 0℃의 물로 변하는 데 약 79.7cal의 용융잠열이 필요하고, 100℃의 물 1g이 100℃ 수증기로 변하는 데 약 539.6cal의 증발잠열이 필요하다고 제시한다.',
    '잠열은 열이 드나들어도 온도는 변하지 않고 상태변화에 사용되는 열이다. 고체↔액체에는 융해잠열, 액체↔기체에는 증발잠열이 연결된다.',
    '교재는 물 1g의 온도를 1℃ 올리는 데 1cal가 필요하다고 비열을 설명하고, 20℃ 물 1g을 100℃까지 올리는 데 80cal가 필요하다는 계산 예를 제시한다. 또한 345쪽에서는 물의 현열(Sensible Heat)을 직접 언급한다. 이 앱에서는 감열과 현열을 같은 온도변화 열 개념으로 연결해 잠열과 비교한다.'
  ],
  must:[
    '물질의 기본 상태 → 고체 · 액체 · 기체',
    '감열(현열) → 상태변화 없이 온도를 변화시키는 데 쓰이는 열',
    '잠열 → 온도변화 없이 상태변화에 쓰이는 열',
    '융해잠열 → 고체 ↔ 액체',
    '증발잠열 → 액체 ↔ 기체',
    '물의 용융잠열 약 79.7cal/g · 증발잠열 약 539.6cal/g'
  ],
  traps:[
    '잠열을 “물질의 온도를 계속 올리는 열”이라고 설명하지 않는다.',
    '감열과 잠열을 같은 구간에 중복 적용하지 않는다. 먼저 온도변화 구간과 상태변화 구간을 나눈다.',
    '20℃ 물을 100℃까지 올리는 열량과 100℃ 물을 수증기로 만드는 잠열을 같은 값으로 보지 않는다.',
    '압력이 달라져도 물의 끓는점이 항상 100℃로 고정된다고 보지 않는다.'
  ],
  compare:[
    ['감열','상태는 유지 · 온도 변화 · 비열과 온도차를 이용'],
    ['잠열','온도는 유지 · 상태 변화'],
    ['융해잠열','고체 ↔ 액체 상태변화'],
    ['증발잠열','액체 ↔ 기체 상태변화']
  ],
  calculations:[
    {title:'감열 계산',formula:'Q = m × c × ΔT',note:'교재의 비열 정의와 190쪽 물 가열 예제를 계산식으로 정리한 관계다. m은 질량, c는 비열, ΔT는 온도차다.',example:'물 1g을 20℃→100℃: 1×1×80 = 80cal'},
    {title:'잠열 계산',formula:'Q = m × L',note:'교재가 제시한 잠열의 단위(cal/g)에 따라 질량과 단위질량당 잠열을 곱한다.',example:'100℃ 물 2g을 수증기로: 2×539.6 = 1,079.2cal'}
  ],
  deepSections:[
    sec('문제를 푸는 순서','① 현재 상태와 최종 상태를 확인한다 → ② 온도만 변하는 구간은 감열로 계산한다 → ③ 상태가 바뀌는 구간은 잠열로 계산한다 → ④ 여러 구간이 있으면 각각 계산한 열량을 합한다.'),
    sec('감열과 잠열을 한눈에 구분','20℃ 물이 100℃ 물이 되는 동안에는 온도가 변하므로 감열 구간이다. 100℃ 물이 100℃ 수증기가 되는 동안에는 온도는 유지되고 상태만 바뀌므로 증발잠열 구간이다.'),
    sec('교재 수치 연결','교재의 물 기준은 비열 1cal/g·℃, 용융잠열 약 79.7cal/g, 증발잠열 약 539.6cal/g이다. 수치문제에서는 단위와 상태변화 구간을 먼저 표시한다.')
  ]
});


add('E11-C03',{
  source:'2026 소방전술3(구급) · 2020년 한국심폐소생술 가이드라인 140~145쪽',
  detail:[
    '성인 심정지 리듬은 심실세동(VF), 무맥성 심실빈맥(pVT), 무수축(asystole), 무맥성 전기활동(PEA) 네 가지로 나누며, VF·pVT는 제세동 가능 리듬, 무수축·PEA는 비제세동 리듬으로 분류한다.',
    '제세동 가능 리듬이 확인되면 즉시 제세동한다. 제세동 후 리듬을 바로 다시 확인하느라 압박을 멈추지 않고 즉시 가슴압박을 재개해 2분간 CPR을 시행한 뒤 리듬을 재평가한다.',
    '성인 심정지 에피네프린은 1mg을 3~5분 간격으로 투여한다. 비제세동 리듬에서는 가능한 한 빨리 투여하고, 제세동 가능 리듬에서는 신속한 제세동을 우선하고 이어지는 CPR 주기에서 투여한다.',
  ],
  must:[
    'Shockable → VF · 무맥성 VT(pVT)',
    'Non-shockable → PEA · asystole',
    'Shockable → 즉시 제세동 → 즉시 2분 CPR → 리듬 재평가',
    'Non-shockable → 즉시 CPR + 조기 에피네프린 → 2분 후 리듬 재평가',
    '에피네프린 → 1mg · 3~5분 간격',
  ],
  traps:[
    'VF/pVT에서 약물 투여 때문에 첫 제세동을 지연하지 않는다.',
    'PEA·무수축에 제세동을 시행하지 않는다.',
    '제세동 직후 바로 리듬을 다시 확인하려고 가슴압박을 오래 멈추지 않는다.',
    '심전도에 전기활동이 보인다는 이유만으로 PEA를 맥박 있는 리듬으로 판단하지 않는다.'
  ],
  compare:[
    ['VF','무질서한 심실 전기활동 · shockable · 즉시 제세동'],
    ['무맥성 VT','빠른 심실빈맥 + 맥박 없음 · shockable · 즉시 제세동'],
    ['PEA','조직된 전기활동 + 맥박 없음 · non-shockable · 원인 교정'],
    ['무수축','유효 심실 전기활동 없음 · non-shockable · CPR/원인 교정']
  ],
  flow:['심정지 확인','리듬 분석','VF/pVT → 제세동','PEA/무수축 → CPR+조기 에피네프린','2분 CPR','리듬 재평가','ROSC 또는 반복'],
  deepSections:[
    sec('심정지 문제를 푸는 첫 분기','리듬 이름을 본 뒤 가장 먼저 “충격 가능한가?”를 판단한다. VF/pVT면 제세동, PEA/무수축이면 제세동 없이 CPR과 원인 교정으로 간다.'),
    sec('제세동 뒤 2분 CPR','충격 뒤 성공 여부를 보기 위해 오래 멈추지 않는다. 즉시 가슴압박을 재개하고 2분간 CPR 후 리듬을 다시 확인하는 흐름을 기억한다.'),
    sec('에피네프린 시점','모든 성인 심정지에서 1mg을 3~5분 간격으로 사용하지만 첫 투여의 우선순위가 다르다. non-shockable은 가능한 빨리, shockable은 빠른 제세동이 먼저다.')
  ],
  officialLinks:[
    {label:'2020년 한국심폐소생술 가이드라인',url:'https://www.kacpr.org/download/2020%EB%85%84%20%ED%95%9C%EA%B5%AD%EC%8B%AC%ED%8F%90%EC%86%8C%EC%83%9D%EC%88%A0%20%EA%B0%80%EC%9D%B4%EB%93%9C%EB%9D%BC%EC%9D%B8.pdf'},
  ]
});
