    '교재는 위험물질·화학물질과 방사선 표시를 현장평가 요소로 다룬다. CBRN의 화학·생물학·방사능/핵 범주는 중앙소방학교 CBRNE 표준교재와 행정안전부 국민안전24 화생방 교육과정으로 보강한다.',
